const H = this.helpers;
const dom = $env.SHOPIFY_STORE_DOMAIN;
const ver = $env.SHOPIFY_API_VERSION || '2025-07';
async function check(service, fn) {
  const t0 = Date.now();
  try { const d = await fn(); return { service, status: 'ok', detail: (d == null ? '' : String(d)).slice(0, 300), latency: Date.now() - t0 }; }
  catch (e) { const m = e && (e.message || e.description) ? (e.message || e.description) : String(e); return { service, status: 'error', detail: String(m).slice(0, 300), latency: Date.now() - t0 }; }
}
const results = [];
results.push(await check('shopify', async () => { const tok = await H.httpRequest({ method: 'POST', url: `https://${dom}/admin/oauth/access_token`, body: { grant_type: 'client_credentials', client_id: $env.SHOPIFY_CLIENT_ID, client_secret: $env.SHOPIFY_CLIENT_SECRET }, json: true }); const shop = await H.httpRequest({ url: `https://${dom}/admin/api/${ver}/shop.json`, headers: { 'X-Shopify-Access-Token': tok.access_token }, json: true }); return shop.shop.name; }));
results.push(await check('openai', async () => { await H.httpRequest({ url: 'https://api.openai.com/v1/models', headers: { Authorization: `Bearer ${$env.OPENAI_API_KEY}` }, json: true }); return 'models accessibles'; }));
results.push(await check('telegram', async () => { const r = await H.httpRequest({ url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/getMe`, json: true }); if (!r.ok) throw new Error('getMe ok=false'); return '@' + r.result.username; }));
results.push(await check('printful', async () => { const r = await H.httpRequest({ url: 'https://api.printful.com/stores', headers: { Authorization: `Bearer ${$env.PRINTFUL_API_KEY}` }, json: true }); return 'stores: ' + ((r.result && r.result.length) || 0); }));
results.push({ service: 'n8n', status: 'ok', detail: 'runtime actif', latency: 0 });
results.push({ service: 'supabase', status: 'ok', detail: 'ecriture connection_health', latency: 0 });
const DELIM = '$cd$';
const esc = (s) => String(s == null ? '' : s).split(DELIM).join('');
const stmts = results.map((r) => `select fn_record_connection_check('${r.service}','${r.status}',${DELIM}${esc(r.detail)}${DELIM},${r.latency | 0});`);
const has_error = results.some((r) => r.status === 'error');
const summary = results.map((r) => `${r.status === 'ok' ? '\u2705' : '\u274c'} ${r.service}${r.detail ? ' \u2014 ' + r.detail : ''}`).join('\n');
return [{ json: { sql: stmts.join('\n'), has_error, summary } }];
